// Validate and normalize all incoming trade inputs
var body = $json.body || $json;
var product = body.product || body.productName || body.product_name || body.title || body.commodity || 'Basmati Rice';
var origin = String(body.origin_country || body.originCountry || body.origin || 'IND').toUpperCase().slice(0,3);
var destination = String(body.destination_country || body.destinationCountry || body.destination || 'ARE').toUpperCase().slice(0,3);
var quantity_kg = Number(body.quantity_kg || body.quantity || body.quantityKg || 50000);
if (quantity_kg <= 0) quantity_kg = 50000;
var target_price_usd = Number(body.target_price_usd || body.targetPriceUSD || body.unitPriceUsd || 1100);
var trade_flow = body.trade_flow || body.tradeFlow || 'Export';
var regime = body.regime || 'balanced';
var certifications = body.certifications || [];
var exporter_name = body.exporter_name || body.exporterName || 'Unspecified Exporter';
var importer_name = body.importer_name || body.importerName || 'Unspecified Importer';
var trade_id = body.trade_id || body.tradeId || ('AUTO-' + Date.now());
// Only run the Ollama-backed LLM synthesis node when the caller actually
// wants a narrative answer. Defaults to true (matches prior behavior); pass
// use_llm:false to skip the ~10-15s local-LLM round trip entirely when the
// caller only needs structured data (tariffs, sanctions, gate decision).
var use_llm = body.use_llm !== undefined ? Boolean(body.use_llm) : true;
var correlation_id = 'globex_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
return [{ json: { product: product, origin_country: origin, destination_country: destination, quantity_kg: quantity_kg, target_price_usd: target_price_usd, trade_flow: trade_flow, regime: regime, certifications: certifications, exporter_name: exporter_name, importer_name: importer_name, trade_id: trade_id, use_llm: use_llm, correlation_id: correlation_id } }];

