var inp  = $('Code - Validate + Normalize Input').item.json;
var hs   = $('HTTP - HS Classifier').item.json;
var xgb  = $('HTTP - XGBoost Demand Forecaster').item.json;
var anom = $('HTTP - IsolationForest Anomaly Engine').item.json;
var rag  = $('HTTP - Compliance RAG Retriever').item.json;
// Only one of these two nodes actually ran this execution (gated by
// IF - Use LLM?); referencing the one that didn't run throws in n8n, so
// fall back to whichever is actually available.
var ragV2;
try { ragV2 = $('HTTP - RAG Query v2 + Ollama Synthesis').item.json; } catch (e) { ragV2 = $('Code - Skip RAG v2 (LLM Not Requested)').item.json; }
var sanctions = $('HTTP - Sanctions Screen').item.json;
var gate = $('HTTP - Transaction Gate').item.json;
var cp   = $('HTTP - Counterparty Match + Sanctions').item.json;
var rpt  = $('HTTP - Multi-Model Report Synthesizer').item.json;

var stages = {
  HS_CLASSIFIER:     hs,
  DEMAND_FORECASTER: xgb,
  ANOMALY_ENGINE:    anom,
  COMPLIANCE_RAG:    rag,
  RAG_QUERY_V2:      ragV2,
  SANCTIONS_SCREEN:  sanctions,
  TRANSACTION_GATE:  gate,
  COUNTERPARTY:      cp,
  REPORT_SYNTHESIS:  rpt
};

var errors = [];
var keys = Object.keys(stages);
for (var i = 0; i < keys.length; i++) {
  var stage = keys[i];
  var data = stages[stage];
  if (data && (data.detail || data.error)) {
    errors.push({
      status: 'FAILED',
      engine: 'n8n',
      failed_stage: stage,
      error: data.detail || data.error,
      execution_id: 'n8n_exec_' + inp.correlation_id,
      retryable: true
    });
  }
}

var overallStatus = errors.length === 0 ? 'SUCCESS' : (errors.length < keys.length ? 'PARTIAL' : 'FAILED');

return [{
  json: {
    status: overallStatus,
    execution_id: 'n8n_exec_' + inp.correlation_id,
    workflow: {
      name: 'GlobeXAI Production Trade Automation OS v2 Sequential',
      nodes_executed: 9,
      duration_ms: Date.now() % 100000
    },
    input: inp,
    results: {
      hs_classification: hs,
      market_opportunity: {
        engine: 'XGBoost Quantile Residual Forecaster Q10/50/90 + LLM Strategist',
        top_recommendations: xgb.top_recommendations || [],
        shap_attribution: xgb.shap_attribution || null,
        top_corridor_ai_synthesis: (xgb.top_recommendations && xgb.top_recommendations[0] && xgb.top_recommendations[0].ai_synthesis) ? xgb.top_recommendations[0].ai_synthesis : null,
        raw: xgb
      },
      anomaly_risk: anom,
      compliance_rag: rag,
      rag_query_v2: {
        synthesized_answer: ragV2.synthesized_answer || null,
        synthesis_available: ragV2.synthesis_available || false,
        synthesis_model: ragV2.synthesis_model || null,
        passages: ragV2.passages || [],
        raw: ragV2
      },
      sanctions_screen: sanctions,
      transaction_gate: gate,
      counterparty: cp,
      report: rpt
    },
    provenance: [
      'POST /predict/hs-code',
      'POST /predict/market-opportunity',
      'POST /api/trade-anomaly/predict',
      'POST /compliance/rag-analyze',
      'POST /api/v1/rag/query',
      'POST /compliance/sanctions-screen',
      'POST /compliance/transaction-gate',
      'POST /predict/counterparty-match',
      'POST /api/v1/trade/generate-report'
    ],
    errors: errors,
    executed_at: new Date().toISOString()
  }
}];
